 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The complete one-cell-wide bars form the frame; recolor them while
    # leaving isolated marks in the same color untouched.
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    bar = next((c for c in set(v for row in grid for v in row) if c != bg), None)
    if bar is None:
        return [row[:] for row in grid]
    rows = [r for r in range(h) if all(grid[r][c] == bar for c in range(w))]
    cols = [c for c in range(w) if all(grid[r][c] == bar for r in range(h))]
    out = [row[:] for row in grid]
    for r in rows:
        for c in range(w):
            out[r][c] = 2
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out
